BEGIN;

SET CONSTRAINTS ALL DEFERRED;

-- service_parts.csv
ON CONFLICT (part_id) DO UPDATE SET part_number = EXCLUDED.part_number, part_name = EXCLUDED.part_name, part_category = EXCLUDED.part_category, part_type = EXCLUDED.part_type, uom = EXCLUDED.uom, unit_cost = EXCLUDED.unit_cost, criticality = EXCLUDED.criticality, abc_class = EXCLUDED.abc_class, replaced_by_part_id = EXCLUDED.replaced_by_part_id, is_active = EXCLUDED.is_active;

COMMIT;
